package com.axiom.analysis;
import com.axiom.analysis.fingerprint.Sha256FailureFingerprinter; import com.axiom.analysis.logs.*; import com.axiom.domain.failure.FailureEventType; import org.junit.jupiter.api.Test; import static org.assertj.core.api.Assertions.assertThat;
class LogProcessingTest { private final LogNormalizer normalizer=new LogNormalizer(); private final FailureEventExtractor extractor=new FailureEventExtractor(new Sha256FailureFingerprinter());
 @Test void stripsAnsiPrefixesRedactsAndAssemblesJavaStack(){var events=normalizer.normalize("2026-09-27T11:21:03.382Z ##[error]\u001B[31mjava.net.ConnectException: Connection refused localhost:5432 token=ghp_abcdefghijklmnopqrstuvwxyz123456\u001B[0m\n\tat app.Db.open(Db.java:91)");assertThat(events).hasSize(1);assertThat(events.getFirst().normalizedMessage()).contains("<PORT>").contains("<REDACTED>");assertThat(events.getFirst().message()).contains("ConnectException");}
 @Test void stableFingerprintNormalizesPortsAndLines(){var a=extractor.extract(normalizer.normalize("java.net.ConnectException: Connection refused localhost:5432\n\tat app.Db.open(Db.java:91)"));var b=extractor.extract(normalizer.normalize("java.net.ConnectException: Connection refused localhost:5433\n\tat app.Db.open(Db.java:124)"));assertThat(a.getFirst().type()).isEqualTo(FailureEventType.CONNECTION_ERROR);assertThat(a.getFirst().fingerprint()).isEqualTo(b.getFirst().fingerprint());}
 @Test void extractsDistinctFailures(){var events=normalizer.normalize("AssertionError: expected 1\nconnection refused\nBUILD FAILED");assertThat(extractor.extract(events)).extracting(x->x.type()).contains(FailureEventType.ASSERTION,FailureEventType.CONNECTION_ERROR,FailureEventType.BUILD_ERROR);}
}
